{
  "openapi": "3.1.0",
  "info": {
    "title": "Nore Client API",
    "version": "1.3.0",
    "description": "Publiczne API Nore Client: wydania, aktualizacje launchera i moda, wydarzenia, aktualności i Nore Hub (kto jeszcze gra z Nore). Bez klucza, CORS otwarty, odpowiedzi z ETag."
  },
  "servers": [
    {
      "url": "https://noroclient.pl"
    }
  ],
  "paths": {
    "/api/v1/status": {
      "get": {
        "summary": "Stan API i synchronizacji w tle",
        "responses": {
          "200": {
            "description": "Stan",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "ok": {
                      "type": "boolean"
                    },
                    "api": {
                      "type": "string"
                    },
                    "latest": {
                      "type": "string"
                    },
                    "sync": {
                      "type": "object",
                      "properties": {
                        "at": {
                          "type": "string"
                        },
                        "ok": {
                          "type": "boolean"
                        },
                        "ms": {
                          "type": "integer"
                        },
                        "releases": {
                          "type": "integer"
                        },
                        "ageSeconds": {
                          "type": "integer"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/version": {
      "get": {
        "summary": "Najnowsze wydanie",
        "responses": {
          "200": {
            "description": "Wydanie",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "version": {
                      "type": "string"
                    },
                    "published": {
                      "type": "string"
                    },
                    "notes": {
                      "type": "string"
                    },
                    "downloads": {
                      "type": "integer"
                    },
                    "assets": {
                      "type": "object",
                      "properties": {
                        "win": {
                          "type": "object",
                          "properties": {
                            "name": {
                              "type": "string"
                            },
                            "size": {
                              "type": "integer"
                            },
                            "url": {
                              "type": "string"
                            },
                            "digest": {
                              "type": [
                                "string",
                                "null"
                              ]
                            },
                            "downloads": {
                              "type": "integer"
                            }
                          }
                        },
                        "linux": {
                          "type": "object",
                          "properties": {
                            "name": {
                              "type": "string"
                            },
                            "size": {
                              "type": "integer"
                            },
                            "url": {
                              "type": "string"
                            },
                            "digest": {
                              "type": [
                                "string",
                                "null"
                              ]
                            },
                            "downloads": {
                              "type": "integer"
                            }
                          }
                        },
                        "mac": {
                          "type": "object",
                          "properties": {
                            "name": {
                              "type": "string"
                            },
                            "size": {
                              "type": "integer"
                            },
                            "url": {
                              "type": "string"
                            },
                            "digest": {
                              "type": [
                                "string",
                                "null"
                              ]
                            },
                            "downloads": {
                              "type": "integer"
                            }
                          }
                        }
                      }
                    },
                    "mods": {
                      "type": "array",
                      "items": {
                        "type": "object",
                        "properties": {
                          "name": {
                            "type": "string"
                          },
                          "size": {
                            "type": "integer"
                          },
                          "url": {
                            "type": "string"
                          },
                          "digest": {
                            "type": [
                              "string",
                              "null"
                            ]
                          },
                          "downloads": {
                            "type": "integer"
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/releases": {
      "get": {
        "summary": "Ostatnie wydania",
        "parameters": [
          {
            "name": "limit",
            "in": "query",
            "schema": {
              "type": "integer",
              "minimum": 1,
              "maximum": 30,
              "default": 10
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Lista",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "count": {
                      "type": "integer"
                    },
                    "releases": {
                      "type": "array",
                      "items": {
                        "type": "object",
                        "properties": {
                          "version": {
                            "type": "string"
                          },
                          "published": {
                            "type": "string"
                          },
                          "downloads": {
                            "type": "integer"
                          },
                          "url": {
                            "type": "string"
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/stats": {
      "get": {
        "summary": "Liczniki pobrań",
        "responses": {
          "200": {
            "description": "Liczniki",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "releases": {
                      "type": "integer"
                    },
                    "downloads": {
                      "type": "object",
                      "properties": {
                        "total": {
                          "type": "integer"
                        },
                        "win": {
                          "type": "integer"
                        },
                        "linux": {
                          "type": "integer"
                        },
                        "mac": {
                          "type": "integer"
                        },
                        "mods": {
                          "type": "integer"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/updates/launcher": {
      "get": {
        "summary": "Aktualizacja launchera",
        "parameters": [
          {
            "name": "platform",
            "in": "query",
            "required": true,
            "schema": {
              "enum": [
                "win",
                "linux",
                "mac"
              ]
            }
          },
          {
            "name": "current",
            "in": "query",
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Wynik",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "update": {
                      "type": "boolean"
                    },
                    "version": {
                      "type": "string"
                    },
                    "download": {
                      "type": "object",
                      "properties": {
                        "name": {
                          "type": "string"
                        },
                        "size": {
                          "type": "integer"
                        },
                        "url": {
                          "type": "string"
                        },
                        "digest": {
                          "type": [
                            "string",
                            "null"
                          ]
                        },
                        "downloads": {
                          "type": "integer"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/updates/mod": {
      "get": {
        "summary": "Plik moda dla wersji Minecraft",
        "parameters": [
          {
            "name": "mc",
            "in": "query",
            "required": true,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "loader",
            "in": "query",
            "schema": {
              "enum": [
                "fabric",
                "forge"
              ]
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Plik",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "mc": {
                      "type": "string"
                    },
                    "loader": {
                      "type": "string"
                    },
                    "platform": {
                      "type": "string"
                    },
                    "java": {
                      "type": "integer"
                    },
                    "jar": {
                      "type": "object",
                      "properties": {
                        "name": {
                          "type": "string"
                        },
                        "size": {
                          "type": "integer"
                        },
                        "url": {
                          "type": "string"
                        },
                        "digest": {
                          "type": [
                            "string",
                            "null"
                          ]
                        },
                        "downloads": {
                          "type": "integer"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/download/{platform}": {
      "get": {
        "summary": "Pobierz instalator",
        "parameters": [
          {
            "name": "platform",
            "in": "path",
            "required": true,
            "schema": {
              "enum": [
                "win",
                "linux",
                "mac"
              ]
            }
          }
        ],
        "responses": {
          "302": {
            "description": "Przekierowanie do pliku w GitHub Releases"
          }
        }
      }
    },
    "/api/v1/events": {
      "get": {
        "summary": "Wydarzenia",
        "responses": {
          "200": {
            "description": "Wydarzenia",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "events": {
                      "type": "array",
                      "items": {
                        "type": "object",
                        "properties": {
                          "id": {
                            "type": "string"
                          },
                          "name": {
                            "type": "string"
                          },
                          "active": {
                            "type": "boolean"
                          },
                          "forced": {
                            "type": "boolean"
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/news": {
      "get": {
        "summary": "Aktualności",
        "responses": {
          "200": {
            "description": "Aktualności",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "news": {
                      "type": "array"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/platforms": {
      "get": {
        "summary": "Obsługiwane wersje",
        "responses": {
          "200": {
            "description": "Platformy",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "platforms": {
                      "type": "array",
                      "items": {
                        "type": "object",
                        "properties": {
                          "name": {
                            "type": "string"
                          },
                          "loader": {
                            "type": "string"
                          },
                          "java": {
                            "type": "integer"
                          },
                          "versions": {
                            "type": "array",
                            "items": {
                              "type": "string"
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/hub/hello": {
      "post": {
        "summary": "Nore Hub: launcher zgłasza gracza (też heartbeat co 60 s)",
        "description": "Podpis ECDSA P-256 (DER, base64) kluczem Nore ID nad: nore-hub/1|name|uuid|hex|ts|online(1/0)|sha256hex(JSON.stringify(cosmetics)). hex = pierwsze 20 znaków sha256(pub). Konto premium: serverId po session/minecraft/join w Mojang. Najwyżej jedno hello na Nore ID co 15 s.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "name",
                  "uuid",
                  "hex",
                  "pub",
                  "ts",
                  "online",
                  "cosmetics",
                  "sig"
                ],
                "properties": {
                  "name": {
                    "type": "string"
                  },
                  "uuid": {
                    "type": "string"
                  },
                  "premium": {
                    "type": "boolean"
                  },
                  "serverId": {
                    "type": "string"
                  },
                  "hex": {
                    "type": "string"
                  },
                  "pub": {
                    "type": "string"
                  },
                  "ts": {
                    "type": "integer"
                  },
                  "online": {
                    "type": "boolean"
                  },
                  "cosmetics": {
                    "type": "object",
                    "description": "Garderoba z moda: { v, slots: { <slot>: { id, color, variant, opts } } }, najwyżej 2048 bajtów",
                    "properties": {
                      "v": {
                        "type": "integer"
                      },
                      "slots": {
                        "type": "object"
                      }
                    }
                  },
                  "sig": {
                    "type": "string"
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Zapisano",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "ok": {
                      "type": "boolean"
                    },
                    "verified": {
                      "type": "boolean"
                    },
                    "name": {
                      "type": "string"
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Złe pola",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    },
                    "status": {
                      "type": "integer"
                    }
                  }
                }
              }
            }
          },
          "401": {
            "description": "Zły podpis, klucz, czas albo brak potwierdzenia Mojang",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    },
                    "status": {
                      "type": "integer"
                    }
                  }
                }
              }
            }
          },
          "409": {
            "description": "Nick należy do innego gracza Nore",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    },
                    "status": {
                      "type": "integer"
                    }
                  }
                }
              }
            }
          },
          "429": {
            "description": "Za często",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    },
                    "status": {
                      "type": "integer"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/hub/players": {
      "get": {
        "summary": "Nore Hub: którzy z tych graczy używają Nore",
        "parameters": [
          {
            "name": "names",
            "in": "query",
            "required": true,
            "description": "Do 100 nicków po przecinku, wielkość liter bez znaczenia",
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Gracze Nore (klucze to nicki małymi literami)",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "players": {
                      "type": "object",
                      "additionalProperties": {
                        "type": "object",
                        "properties": {
                          "name": {
                            "type": "string"
                          },
                          "uuid": {
                            "type": "string"
                          },
                          "hex": {
                            "type": "string"
                          },
                          "verified": {
                            "type": "boolean"
                          },
                          "online": {
                            "type": "boolean"
                          },
                          "seen": {
                            "type": "integer"
                          },
                          "cosmetics": {
                            "type": "object",
                            "description": "Garderoba z moda: { v, slots: { <slot>: { id, color, variant, opts } } }, najwyżej 2048 bajtów",
                            "properties": {
                              "v": {
                                "type": "integer"
                              },
                              "slots": {
                                "type": "object"
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Za dużo nicków",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    },
                    "status": {
                      "type": "integer"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/hub/stats": {
      "get": {
        "summary": "Nore Hub: liczba graczy",
        "responses": {
          "200": {
            "description": "Liczniki",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "online": {
                      "type": "integer"
                    },
                    "known": {
                      "type": "integer"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/v1/launcher/config": {
      "get": {
        "summary": "Ustawienia dla Nore Launchera",
        "responses": {
          "200": {
            "description": "Ustawienia",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "microsoftClientId": {
                      "type": [
                        "string",
                        "null"
                      ]
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

{
  "news": [
